});

// "Decide": joins the Slack event with the thread's saved row and picks a route for "Route".
// script stage: a reply revises the draft, "Approve script" makes the video, "Reject" ends it.
// video stage: a reply revises and remakes the video, "Approve and publish" posts to the outlet.
// A tap on an old button, or anything in a finished thread, is ignored.
const ev = $("Read Slack event").first().json;
const row = $input.first().json;
let state;
try {
  state = JSON.parse(row.state);
} catch {
  return [];
}
const stage = row.stage;
const run = state.run;
const history = state.history || [];
const chat = { thread_ts: ev.thread_ts, stage, history, user: ev.user, text: ev.text || "" };

let route = "";
if (ev.kind === "action") {
  if (ev.action === "approve_script" && stage === "script") route = "approve_script";
  else if (ev.action === "approve_video" && stage === "video") route = "approve_video";
  else if (ev.action === "reject" && (stage === "script" || stage === "video")) route = "reject";
} else if (ev.kind === "reply" && (stage === "script" || stage === "video")) {
  route = "revise";
}
if (!route) return [];

const item = { ...run, chat, route };
if (route === "approve_script") {
  item.working_note = "Script approved. Recording the voice and making the video; this takes about 20 seconds.";
}
if (route === "revise") {
  const ask = {
    stage: stage === "script" ? "script review: no voice or video made yet" : "video review: the editor has seen the video",
    client: { name: run.client?.name, style: run.client?.style },
    story: run.story,
    news_reports: (run.reports || []).map(({ id, source, title, summary }) => ({ id, source, title, summary })),
    current_draft: draftOf(run),
    conversation: history,
    editor_message: ev.text,
  };
  item.claude_body = {
    model: "claude-haiku-5-5",
    max_tokens: 4000,
    output_config: { effort: "low" },
    system: "You are the newsReels bot for a client outlet, named in the request with its style card. An editor is reviewing a short data video in a Slack thread and has replied to you. You get one JSON object: the client, the story worked out from open data, recent news reports from the client's feeds, the current draft, the review stage, the conversation so far, and the editor's new message.\n\nDecide what the editor wants:\n- A change to the draft: make it, keeping everything they did not ask to change.\n- A question about the data or the draft: answer it from the story JSON and the news reports only.\n- Something you cannot do (a number that is not in the story, a cause the data does not show, a change to the voice, colours or video length): say so plainly and offer what you can do.\n\nThe draft has these fields, all strings except reports_used:\n- headline: at most 8 words\n- script: 35 to 45 words, 3 sentences, read aloud in under 18 seconds. Say \"this week\", never a date. Name at most 2 neighbourhoods. The source is shown on screen, so the script does not name it\n- callout_label: one line under the big number\n- chart_title: what the bars show\n- chart_kind: \"by_area\" (this week by neighbourhood, top 6) or \"weekly\" (the count for each of the last 6 weeks). Either is fine when the editor asks for it; if by_area is empty, only \"weekly\" is possible. When you change it, make chart_title fit\n- blurb: 2 sentences for the newsletter, naming the source from source_note and the source of each report used\n- reports_used: the ids of the news reports the draft draws on, such as [\"r1\"], or []. Keep it matching the script: add an id when you use a report, remove it when you remove that report's sentence\n\nRules for anything you write, in the draft or in your reply:\n- Use only numbers that appear in the story JSON, or in a report listed in reports_used, written in digits exactly as they appear there. Never round, add, subtract or work out a new number. Write \"8 weeks\", not \"eight weeks\".\n- Never mention an address, street or person.\n- Plain, calm, specific. No hype, no exclamation marks, no guessing at causes.\n- Talk to the editor in plain words. Never name the JSON fields (say \"the neighbourhood chart\", not by_area).\n\nReturn only a JSON object, no other text:\n{\"reply\": \"one or two short sentences to the editor saying what you changed or answering them\", \"draft\": {the full draft with all seven fields} or null if nothing should change}\n",
    messages: [{ role: "user", content: JSON.stringify(ask, null, 2) }],
  };
}
return [{ json: item }];

// Shared by "3 Write" and "7 Chat" (build.mjs puts it at the top of their Code nodes).
// Turns a draft (headline, script, callout_label, chart_title, chart_kind, blurb, reports_used) into the
// render spec, builds the chart from the story itself, and lists every problem the guard finds
// (must-work row 9). A number may come from the story or from a news report the draft says it used.
// `ctx` is the run's client (name, look, style card) and its recent reports.
const numbersIn = (text) => (String(text).match(/\d[\d,]*(?:\.\d+)?/g) || []).map((m) => Number(m.replace(/,/g, "")));

// Where each allowed number comes from, most specific place first. The trace shows these.
function numberOrigins(story, used = []) {
  const origin = new Map();
  const note = (n, where) => { if (!origin.has(n)) origin.set(n, where); };
  note(7, "the window: 7 days"); note(8, "the window: 8 weeks"); note(9, "the window: 9 weeks");
  for (const [k, v] of Object.entries(story)) if (typeof v === "number") { note(v, `story ${k}`); note(Math.abs(v), `story ${k}`); }
  for (const a of story.by_area || []) note(a.count, `story by_area, ${a.area}`);
  for (const x of story.weekly || []) note(x.count, `story weekly, week ending ${x.week_ending}`);
  for (const n of numbersIn(JSON.stringify(story))) note(n, "story");
  for (const r of used) for (const n of numbersIn(`${r.title} ${r.summary}`)) note(n, `report ${r.id}, ${r.source}`);
  return origin;
}

function unknownNumbers(story, fields, used = []) {
  const origin = numberOrigins(story, used);
  const unknown = [];
  for (const [field, text] of Object.entries(fields)) {
    for (const n of numbersIn(text)) if (!origin.has(n)) unknown.push(`${n} in ${field}`);
  }
  return unknown;
}

